$ErrorActionPreference='Stop'
$js=@'
const ctl=new AbortController();setTimeout(()=>ctl.abort(),4500);
try{
const tabs=await(await fetch("http://127.0.0.1:17447/json/list",{signal:ctl.signal})).json();
const t=tabs.find(x=>x.url.startsWith("https://www.avito.ru/krasnoyarsk/") && x.webSocketDebuggerUrl);
if(!t)throw new Error("Avito tab missing");
const ws=new WebSocket(t.webSocketDebuggerUrl);
const out=await Promise.race([
new Promise((resolve,reject)=>{
ws.addEventListener("open",()=>{
ws.send(JSON.stringify({id:77,method:"Runtime.evaluate",params:{expression:"({title:document.title,markerCount:document.querySelectorAll('[data-marker=item]').length,linkCount:document.querySelectorAll('a[href]').length})",returnByValue:true}}))},{once:true});
ws.addEventListener("message",e=>{let r=JSON.parse(e.data);if(r.id===77)resolve(r.result?.result?.value||{error:r.error?.message?.slice(0,50)})});
ws.addEventListener("error",reject,{once:true});
}),
new Promise((_,reject)=>setTimeout(()=>reject(new Error("timeout")),5000))
]);
console.log(JSON.stringify(out));ws.close()
}catch(e){console.log(JSON.stringify({error:String(e).slice(0,150)}))}
process.exit(0)
'@
$tmp=Join-Path $env:TEMP 'pc-public-avito-count.mjs'
try{[System.IO.File]::WriteAllText($tmp,$js,[System.Text.UTF8Encoding]::new($false));& node.exe $tmp}finally{Remove-Item -LiteralPath $tmp -ErrorAction SilentlyContinue -Force}
